import type { Metadata } from 'next';
import Link from 'next/link';
import { headers } from 'next/headers';
import { ViewAllPostsButton } from '@/components/ViewAllPostsButton';

interface Post {
  id: number;
  title: string;
  body: string;
}

async function getHomeData(): Promise<{
  posts: Post[];
  userAgent: string;
  timestamp: string;
}> {
  const headersList = await headers();
  const userAgent = headersList.get('user-agent') || '';
  const posts = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5',
    { cache: 'no-store' }
  ).then((res) => res.json());

  return {
    posts,
    userAgent,
    timestamp: new Date().toISOString(),
  };
}

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
};

export default async function HomePage() {
  const { posts, userAgent, timestamp } = await getHomeData();

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <ViewAllPostsButton />
    </div>
  );
}

